        'registros_textuales_clinicos' => [
            'crear' => 'CREATE TABLE registros_textuales_clinicos (cod_registro_textual varchar(20) NOT NULL, tipo_evento varchar(20) NOT NULL, cod_atencion character varying(20), cod_residente character varying(20), cod_personal character varying(20), cod_nota_anterior character varying(20), tipo_nota character varying(50), contenido text, fecha_hora timestamp(0), motivo_correccion text, estado character varying(20), tipo_indicacion character varying(40), descripcion text, prioridad character varying(20), observacion text, cod_nota character varying(20) GENERATED ALWAYS AS (CASE
    WHEN ((tipo_evento) = \'NOTA\') THEN cod_registro_textual
    ELSE NULL
END) STORED, cod_indicacion character varying(20) GENERATED ALWAYS AS (CASE
