            'triggers' => [
                0 => [
                    'name' => 'vpo_contrato',
                    'sql' => 'CREATE TRIGGER vpo_contrato BEFORE INSERT ON valoraciones_petersen_originales WHEN NOT (length(trim(NEW.justificacion)) > 0 AND NEW.elemento IN (\'COG-MEM\',\'COG-ATE\',\'COG-EJE\',\'COG-LEN\',\'COG-VIS\',\'C01\',\'C03\',\'C04\',\'C05\') AND ((NEW.tipo_registro=\'REGISTRO\' AND NEW.cod_valoracion_anterior IS NULL) OR (NEW.tipo_registro IN (\'RECTIFICACION\',\'ANULACION\') AND NEW.cod_valoracion_anterior IS NOT NULL AND NEW.cod_valoracion_anterior <> NEW.cod_valoracion_petersen)) AND ((NEW.tipo_registro=\'ANULACION\' AND NEW.estado_original IS NULL) OR (NEW.tipo_registro <> \'ANULACION\' AND NEW.estado_original IS NOT NULL AND ((NEW.elemento LIKE \'COG-%\' AND NEW.estado_original IN (\'A\',\'P\',\'I\')) OR (NEW.elemento NOT LIKE \'COG-%\' AND NEW.estado_original IN (\'S\',\'N\'))))) AND ((NEW.cod_documento_clinico IS NULL AND NEW.localizador_fuente IS NULL) OR (NEW.cod_documento_clinico IS NOT NULL AND NEW.localizador_fuente IS NOT NULL AND length(trim(NEW.localizador_fuente))>0)) AND (NEW.alcance_dominio IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento LIKE \'COG-%\'))) AND (NEW.contexto_interpretado IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento LIKE \'COG-%\'))) AND (NEW.cambio_respecto_previo IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C01\'))) AND (NEW.corroboracion_independiente IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C01\'))) AND (NEW.revision_integrada IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C03\'))) AND (NEW.oportunidad_adecuada IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C03\'))) AND (NEW.atribucion_revisada IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C03\'))) AND (NEW.revision_explicita IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C04\'))) AND (NEW.factores_pertinentes_revisados IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C04\'))) AND (NEW.impedimento_no_resuelto IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C04\'))) AND (NEW.suficiencia_conjunto IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C05\'))) AND (NEW.condiciones_revisadas IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C05\'))) AND (NEW.exclusiones_revisadas IS NULL OR (NEW.tipo_registro <> \'ANULACION\' AND (NEW.elemento = \'C05\')))) BEGIN SELECT RAISE(ABORT, \'Contrato Petersen incompatible\'); END',
                ],
